// Get date range for the past week
const now = new Date();
const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const formatDate = (date) => {
  return date.toISOString().split('T')[0];
};

return [{
  json: {
    since: formatDate(oneWeekAgo),
    until: formatDate(now),
    week_start: formatDate(oneWeekAgo),
    week_end: formatDate(now)
  }
}];

// Process commits, issues, and PRs for Claude
const commits = $input.all()[0]?.json || [];
const issues = $input.all()[1]?.json || [];
const prs = $input.all()[2]?.json || [];

// Calculate week range
const weekRange = $('Calculate Week Range').item.json;

// Process commits
const commitSummary = {
  total: commits.length,
  byAuthor: {},
  messages: commits.slice(0, 20).map(c => ({
    message: c.message,
    author: c.author?.name || 'Unknown',
    date: c.date
  }))
};

commits.forEach(c => {
  const author = c.author?.name || 'Unknown';
  commitSummary.byAuthor[author] = (commitSummary.byAuthor[author] || 0) + 1;
});

// Process issues
const issueSummary = {
  opened: issues.filter(i => {
    const created = new Date(i.created_at);
    const since = new Date(weekRange.since);
    return created >= since;
  }).length,
  closed: issues.filter(i => {
    if (!i.closed_at) return false;
    const closed = new Date(i.closed_at);
    const since = new Date(weekRange.since);
    return closed >= since;
  }).length,
  total: issues.length
};

// Process PRs
const prSummary = {
  opened: prs.filter(p => {
    const created = new Date(p.created_at);
    const since = new Date(weekRange.since);
    return created >= since;
  }).length,
  merged: prs.filter(p => {
    if (!p.merged_at) return false;
    const merged = new Date(p.merged_at);
    const since = new Date(weekRange.since);
    return merged >= since;
  }).length,
  total: prs.length
};

return [{
  json: {
    week_range: weekRange,
    commits: commitSummary,
    issues: issueSummary,
    pull_requests: prSummary,
    raw: {
      commits: commits.slice(0, 10),
      issues: issues.slice(0, 10),
      prs: prs.slice(0, 10)
    }
  }
}];

